INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(19301, 'Lamentations 3:60', 'Lamentations', 3, 60, '&nbsp;تا د هغوئ د انتقام ټول اور وليدو، د هغوئ ټولې منصوبې زما خلاف دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19302, 'Lamentations 3:61', 'Lamentations', 3, 61, '&nbsp;اے مالِکه خُدايه، تا د هغوئ ټول پيغورونه واورېدل، د هغوئ ټولې منصوبې چې زما خلاف دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19303, 'Lamentations 3:62', 'Lamentations', 3, 62, '&nbsp;زما مخالفين ټوله ورځ زما خلاف پس پس او ګنګوسى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19304, 'Lamentations 3:63', 'Lamentations', 3, 63, '&nbsp;هغوئ ته وګوره، سحر نه تر ماښامه پورې، زۀ د هغوئ د پيغورونو په سندرو کښې نمونه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19305, 'Lamentations 3:64', 'Lamentations', 3, 64, '&nbsp;اے مالِکه خُدايه، هغوئ ته بدله ورکړه، هغوئ ته د خپل عمل په مطابق بدله ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19306, 'Lamentations 3:65', 'Lamentations', 3, 65, '&nbsp;هغوئ په زړونو غمژن کړه او ستا لعنت دې په هغوئ باندې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19307, 'Lamentations 3:66', 'Lamentations', 3, 66, '&nbsp;هغوئ په خپله غصه کښې راونيسه، مالِکه خُدايه، د زمکې د مخ نه يې جارُو کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19308, 'Lamentations 4:1', 'Lamentations', 4, 1, '&nbsp;وګورئ چې د سرو زرو ځلا څنګه تته شوه، او چې خالص سرۀ زر څنګه بدل شوى دى، او د مقدس ځائ کاڼى د هر يو سړک په هر ګوټ کښې خوارۀ وارۀ شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19309, 'Lamentations 4:2', 'Lamentations', 4, 2, '&nbsp;د صيون بيش قيمته ماشومان، چې د خالص سرو زرو په تول وُو، خو اوس هغه لکه د خاورين لوښو په شان دى، لکه چې کُلال جوړ کړى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19310, 'Lamentations 4:3', 'Lamentations', 4, 3, '&nbsp;تر دې چې ګيدړه هم خپلو ماشومانو ته سينه ورکوى، خو زما خلق ظالمان شوى دى لکه شتر‌مرغ چې په صحرا کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19311, 'Lamentations 4:4', 'Lamentations', 4, 4, '&nbsp;د پيو د ماشومانو ژبې انښتې دى او د تندې نه تالو ته ورغلې دى. ماشومان روټۍ پسې ژاړى خو هيچا سره هم نشته چې هغوئ له ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19312, 'Lamentations 4:5', 'Lamentations', 4, 5, '&nbsp;هغه چا چې به خوندور خوراکونه کول هغوئ اوس په کوڅو کښې د لوږى نه مړۀ کيږى. هغوئ چا چې به قيمتى کپړې استعمالولې اوس هغوئ د ګند په ډېرو کښې د خوراک لټون کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19313, 'Lamentations 4:6', 'Lamentations', 4, 6, '&nbsp;زما د خلقو سزا د سدوم د خلقو نه زياته ده، کوم چې په يو شېبه کښې تباه شُو او هيچا پرې لاس ونۀ مروړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19314, 'Lamentations 4:7', 'Lamentations', 4, 7, '&nbsp;د صيون حکمرانان د واورې نه زيات صفا وُو او د پيو نه زيات سپين وُو. د هغوئ بدن د مرجانو نه زيات سور وو، او د هغوئ شکلونه او صورتونه د نيلم کاڼى په شان ښکارېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19315, 'Lamentations 4:8', 'Lamentations', 4, 8, '&nbsp;خو اوس د هغوئ مخونه سکارو نه زيات تور دى. هغوئ په لارو کوڅو کښې د خلقو د پېژندګلو نه وتى دى. د هغوئ څرمن د هغوئ هډوکو پورې انښتې ده او هغه لکه د پوستکى په شان اوچه شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19316, 'Lamentations 4:9', 'Lamentations', 4, 9, '&nbsp;هغوئ څوک چې په تُوره مړۀ شوى وُو د هغه چا نه ښۀ وُو چې د قحط نه مړۀ شوى وُو. او د پټى نه د فصل د نشتوالى په وجه هغوئ د لوږو نه مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19317, 'Lamentations 4:10', 'Lamentations', 4, 10, '&nbsp;کله چې زما قوم تباه کېدو نو د لوږې نه مهربانه ميندو هم خپل ماشومان پاخۀ کړل او وې خوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19318, 'Lamentations 4:11', 'Lamentations', 4, 11, '&nbsp;مالِک خُدائ خپل ټول غضب په دوئ ظاهر کړو او هغۀ خپل سخت قهر رانازل کړو. هغۀ په صيون کښې اور بل کړو. او هغه يې تر بنيادونو وسوزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19319, 'Lamentations 4:12', 'Lamentations', 4, 12, '&nbsp;د دُنيا بادشاهانو په دې يقين نۀ کولو، او نۀ پرې د دُنيا يو اوسېدونکى باور کولو، چې مخالفين او دشمنان به د يروشلم په لويو دروازو کښې راننوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19320, 'Lamentations 4:13', 'Lamentations', 4, 13, '&nbsp;خو دا د هغې د پېغمبرانو د ګناه په وجه وشو او د اِمامانو په جرمونو سره وشو، چا چې د ښار په مينځ کښې د صادقانو وينه تويه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19321, 'Lamentations 4:14', 'Lamentations', 4, 14, '&nbsp;هغوئ لکه د ړندو په کوڅو کښې سرګردانه ګرځېدل. او په وينو داسې لت پت وُو چې چا يې جامو له د لاس وروړلو جرأت نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19322, 'Lamentations 4:15', 'Lamentations', 4, 15, '&nbsp;”اخوا شئ ناپاکو،“ خلقو په هغوئ چغې ووهلې، ”اخوا شئ، اخوا شئ، لاس مۀ راوړئ.“ نو بيا هغوئ لرې وطنونو ته وتښتېدل او په غېرو قومونو کښې سرګردانه ګرځېدل خو هيچا هلته پاتې کېدلو ته نۀ پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19323, 'Lamentations 4:16', 'Lamentations', 4, 16, '&nbsp;مالِک خُدائ په خپله هغوئ خوارۀ وارۀ کړل او نور يې د هغوئ قدر نۀ کولو. خلقو نۀ د اِمامانو عزت کولو او نۀ يې په مشرانو رحم کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19324, 'Lamentations 4:17', 'Lamentations', 4, 17, '&nbsp;په ډېرو کتو مو سترګې ړندې شوې خو بې‌فائدې، هيڅ مدد رانۀ غلو. مونږ د داسې يو قوم په انتظار وُو چې زمونږ بچ کول د هغوئ د وس کار نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19325, 'Lamentations 4:18', 'Lamentations', 4, 18, '&nbsp;مونږ په خپلو کوڅو کښې نۀ شُو ګرځېدلے ځکه چې دشمن راته مورچه شوے دے. زمونږ آخر رانزدې شوے وو، او زمونږ ورځې شمېرلے شوې وې، ځکه چې زمونږ اَنجام رارسېدلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19326, 'Lamentations 4:19', 'Lamentations', 4, 19, '&nbsp;زمونږ دشمنان به د باز نه زيات تېز وُو، کۀ مونږ به غرونو ته وزغلېدو نو هلته به يې پېدا کړُو او کۀ په صحرا کښې به پټ شُو نو هغوئ به هلته زمونږ انتظار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19327, 'Lamentations 4:20', 'Lamentations', 4, 20, '&nbsp;د مالِک خُدائ غوره کړے شوے بادشاه چې زمونږ د ژوند ساه ده، هغه د هغوئ په دام کښې راګېر شوے وو، د چا په حقله چې مونږ وئيل چې، ”د هغۀ د سورى د لاندې به مونږ د قومونو په مينځ کښې اوسيږو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19328, 'Lamentations 4:21', 'Lamentations', 4, 21, '&nbsp;اے د ادوم لورې، اوس خندا او خوشحالى وکړه، او تاسو څوک چې په عُوض کښې اوسېږئ، تاسو ته به هم د مالِک خُدائ د غضب پياله درکړے شى، تاسو به نشه شئ او خپل ځان به بربنډ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19329, 'Lamentations 4:22', 'Lamentations', 4, 22, '&nbsp;اے صيون لورې، ستا سزا به پوره شى، هغه به تا نور په جلاوطنۍ کښې ونۀ ساتى. خو اے د ادوم لورې، هغه به تا له ستا د ګناهونو سزا درکړى او ستا ګناهونه به ښکاره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19330, 'Lamentations 5:1', 'Lamentations', 5, 1, '&nbsp;اے مالِکه خُدايه، راياد کړه چې په مونږ څۀ وشو، وګوره چې زمونږ څنګه بې‌عزتى شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19331, 'Lamentations 5:2', 'Lamentations', 5, 2, '&nbsp;زمونږ ميراث غېرو ته حواله شوے دے او زمونږ کورونه پردو خلقو قبضه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19332, 'Lamentations 5:3', 'Lamentations', 5, 3, '&nbsp;مونږ يتيمان او بې‌پلاره شوى يُو او زمونږ ميندې کونډې شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19333, 'Lamentations 5:4', 'Lamentations', 5, 4, '&nbsp;مونږ د څښلو اوبۀ او د سوزولو خشاک په بيعه اخلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19334, 'Lamentations 5:5', 'Lamentations', 5, 5, '&nbsp;هغوئ څوک چې مونږ پسې وُو راته په سر ناست دى او مونږ ډېر ستومانه شُو خو هيڅ آرام ته مو نۀ پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19335, 'Lamentations 5:6', 'Lamentations', 5, 6, '&nbsp;مونږ خپل ځان مِصر او اسور ته حواله کړو چې مونږ ته پوره روټۍ مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19336, 'Lamentations 5:7', 'Lamentations', 5, 7, '&nbsp;زمونږ پلار نيکۀ ګناه وکړه خو هغوئ مړۀ دى او اوس مونږ د هغوئ د ګناه سزا خورو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19337, 'Lamentations 5:8', 'Lamentations', 5, 8, '&nbsp;غلامان په مونږ حکومت کوى او هيڅ څوک نشته چې مونږ د هغوئ د لاس نه آزاد کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19338, 'Lamentations 5:9', 'Lamentations', 5, 9, '&nbsp;مونږ د روټۍ پېدا کولو دپاره خپل ځان په خطره کښې اچولے دے ځکه چې په ټوله علاقه کښې وسله وال ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19339, 'Lamentations 5:10', 'Lamentations', 5, 10, '&nbsp;زمونږ څرمن لکه د تنور په شان ګرمه ده، د قحط د ډېر تاو نه سوزېدلې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19340, 'Lamentations 5:11', 'Lamentations', 5, 11, '&nbsp;په صيون کښې د ښځو عزت لوټ شوے دے او د يهوداه په ښارونو کښې د پېغلو عزت لوټ شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19341, 'Lamentations 5:12', 'Lamentations', 5, 12, '&nbsp;دوئ شهزادګان د لاسونو نه راځوړند کړى دى او د مشرانو بې‌عزتى يې کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19342, 'Lamentations 5:13', 'Lamentations', 5, 13, '&nbsp;په ځوانانو په زور مېچنې ګرځولے شى، او زلمى د لرګو د درنو بارونو لاندې په تکليف روان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19343, 'Lamentations 5:14', 'Lamentations', 5, 14, '&nbsp;مشرانو د ښار په دروازه د جرګو ځايونه پرېښودل او ځوانانو خپل ساز و سرود پرېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19344, 'Lamentations 5:15', 'Lamentations', 5, 15, '&nbsp;زمونږ د زړۀ خوشحالى رانه اخستے شوې ده او زمونږ ګډا په ماتم بدله شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19345, 'Lamentations 5:16', 'Lamentations', 5, 16, '&nbsp;زمونږ نه تاج و تخت اخستلے شوے دے، افسوس په مونږ ځکه چې مونږ ګناه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19346, 'Lamentations 5:17', 'Lamentations', 5, 17, '&nbsp;ځکه د دې په وجه زمونږ زړونه مات شوى دى او د ژړا په وجه زمونږ نظر کم شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19347, 'Lamentations 5:18', 'Lamentations', 5, 18, '&nbsp;دا چې د صيون غر وران ويجاړ پروت دے او ګيدړان په کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19348, 'Lamentations 5:19', 'Lamentations', 5, 19, '&nbsp;خو تۀ اے مالِکه خُدايه، د تل دپاره حکومت کوې او ستا تخت په ټولو نسلونو کښې قائم پاتې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19349, 'Lamentations 5:20', 'Lamentations', 5, 20, '&nbsp;تا ولې مونږ بلکل هېر کړى يُو؟ تا ولې مونږ ډېرو ورځو نه پرېښى يُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19350, 'Lamentations 5:21', 'Lamentations', 5, 21, '&nbsp;اے مالِکه خُدايه مونږ ځان ته راوبله، مونږ بحال کړه او زمونږ حال د مخکښې په شان کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19351, 'Lamentations 5:22', 'Lamentations', 5, 22, '&nbsp;ولې تا مونږ تل دپاره رد کړى يُو؟ او تۀ مونږ ته د حد نه زيات غصه يې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19352, 'Ezekiel 1:1', 'Ezekiel', 1, 1, '&nbsp;په دېرشم کال د څلورمې مياشتې په پينځمه ورځ، کله چې زۀ حزقى‌ايل د جلاوطنو سره د کبار د سيند په غاړه ولاړ وم، نو ما آسمان کولاو وليدو او خُدائ پاک ما ته روياګانې وښودلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19353, 'Ezekiel 1:2', 'Ezekiel', 1, 2, '&nbsp;د مياشتې په پينځم تاريخ دا د يهوياکين بادشاه د جلاوطنۍ پينځم کال وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19354, 'Ezekiel 1:3', 'Ezekiel', 1, 3, '&nbsp;د مالِک خُدائ کلام په حزقى‌ايل اِمام، د بوزى په زوئ باندې د کبار د سيند په غاړه د بابل په مُلک کښې نازل شو او د مالِک خُدائ لاس په هغۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19355, 'Ezekiel 1:4', 'Ezekiel', 1, 4, '&nbsp;کله چې ما بره وکتل، نو ما يو لوئ طوفان د شمال د خوا نه په راتلو وليدلو چې لويه وريځ ترې مخکښې وه چې د برېښنا پړقېدل او ګېرچاپېره ترې نه تېزه رڼا خوره وه. د وريځو په مينځ کښې اور وو او د اور په مينځ کښې يو د پيتلو په شان څيز ځلېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19356, 'Ezekiel 1:5', 'Ezekiel', 1, 5, '&nbsp;او د وريځو د مينځ نه څلور ژوندى مخلوقات راووتل چې په ليدو کښې د انسان په شان ښکارېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19357, 'Ezekiel 1:6', 'Ezekiel', 1, 6, '&nbsp;خو د هغوئ هر يو څلور مخونه او څلور وزرونه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19358, 'Ezekiel 1:7', 'Ezekiel', 1, 7, '&nbsp;د هغوئ پښې نېغې وې، او په پښو کښې يې لکه د سخى په شان نوکونه وُو او هغه لکه د پالش شوى پيتلو په شان ځلېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19359, 'Ezekiel 1:8', 'Ezekiel', 1, 8, '&nbsp;او د هغوئ د څلورو وزرونو لاندې څلورو طرفونو ته د انسان په شان لاسونه وُو او د هر يو مخلوق څلور مخونه او څلور وزرونه وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19360, 'Ezekiel 1:9', 'Ezekiel', 1, 9, '&nbsp;او د هغوئ وزرونه د يو بل سره لګېدلى وُو. او هر يو نېغ روان شو، نو د تلو په وخت کښې به تاوېدل راتاوېدل نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19361, 'Ezekiel 1:10', 'Ezekiel', 1, 10, '&nbsp;د هر يو څلور مخونه وُو چې په مخامخ د هر يو شکل د انسان وو، او په ښې طرف هغوئ د زمرى په شکل وو، ګس طرف ته يې د غوائى شکل وو، او شاته لکه د باز په شان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19362, 'Ezekiel 1:11', 'Ezekiel', 1, 11, '&nbsp;د هر يو مخلوق وزرې بره طرف ته خورې وې، د هر يو دوه وزرې ګس او ښى طرف ته د نور مخلوق وزرو سره لګېدلې وې او په نورو دوو وزرو يې خپل بدن پټ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19363, 'Ezekiel 1:12', 'Ezekiel', 1, 12, '&nbsp;هر يو نېغ مخکښې لاړو، کومې خوا ته چې به د روح خوښه وه نو هغې خوا ته به بغېر د راتاوېدلو نه نېغ تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19364, 'Ezekiel 1:13', 'Ezekiel', 1, 13, '&nbsp;دا ژوندے مخلوق داسې ښکاريدو لکه چې بَل سکارۀ يا د اور مشعلونه د هغوئ دننه بل شوى وى. دا اور د هغه مخلوق په مينځ کښې وړاندې وروستو کېدو، او دا ځلېدونکى وُو، او شُغلې به ترې نه راختلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19365, 'Ezekiel 1:14', 'Ezekiel', 1, 14, '&nbsp;هغه مخلوق به لکه د برېښنا د پړق په شان په منډه وړاندې او وروستو کېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19366, 'Ezekiel 1:15', 'Ezekiel', 1, 15, '&nbsp;کله چې ما دې ژوندى مخلوق ته وکتل، نو ما د هغوئ هر يو سره په زمکه باندې يوه پايه لګېدلې وليدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19367, 'Ezekiel 1:16', 'Ezekiel', 1, 16, '&nbsp;د هغه پايو شکل او ښکاره کېدل څۀ داسې وو، هغه لکه د ايکوامرين کاڼو په شان ځلېدلې، او څلور واړه پايې يو شان ښکارېدلې، او داسې جوړې شوې وې چې په هره پايه کښې يوه بله پايه دننه بل خوا ته تاوېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19368, 'Ezekiel 1:17', 'Ezekiel', 1, 17, '&nbsp;کله چې به هغوئ تلل نو دې ژوندى مخلوق به په څلورو اړخونو کښې چې کوم طرف ته هم مخه کړه نو هغې خوا ته به بغېر د مخ اړولو نه تللے شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19369, 'Ezekiel 1:18', 'Ezekiel', 1, 18, '&nbsp;د څلور واړو پايو ريمونه لوړ او يروونکى وُو، او په هغه څلورو واړو ريمونو باندې ګېرچاپېره سترګې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19370, 'Ezekiel 1:19', 'Ezekiel', 1, 19, '&nbsp;کله به چې دا مخلوق ګرځېدل نو دا پايې به هم ورسره ګرځېدلې، او کله به چې دا مخلوق د زمکې نه راپاڅېدل نو دا پايې به هم ورسره اوچتې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19371, 'Ezekiel 1:20', 'Ezekiel', 1, 20, '&nbsp;چرته به چې روح تللو نو هغوئ به هم هلته تلل، دا پايې به هم ورسره راوچتېدلې، ځکه چې د ژوندى مخلوق روح په هغه پايو کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19372, 'Ezekiel 1:21', 'Ezekiel', 1, 21, '&nbsp;نو کله چې به دا مخلوق روان شو نو دا پايې به هم روانې شوې، کله به چې دا مخلوق ودرېدو نو پايې به هم ودرېدې، کله به چې دا مخلوق بره الوتلو نو دا پايې به ورسره تلې، ځکه چې د دې ژوندى مخلوق روح په پايو کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19373, 'Ezekiel 1:22', 'Ezekiel', 1, 22, '&nbsp;د دې مخلوق د سر دپاسه داسې ګنبد خور شوے وو چې د صفا او روښانه بلور کاڼى په شان ځلېدو او ډېر حېرانونکے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19374, 'Ezekiel 1:23', 'Ezekiel', 1, 23, '&nbsp;د هغه ګنبد د لاندې هغوئ به خپلې وزرې غوړولې او وزرې به يې يو بل پورې غزولې، او هر يو به په خپلو نورو دوو وزرو خپل بدن پټولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19375, 'Ezekiel 1:24', 'Ezekiel', 1, 24, '&nbsp;کله چې دا مخلوق روانېدلو، نو ما د هغوئ د وزرونو آواز واورېدو لکه د تېزو اوبو د شور په شان، لکه د قادر خُدائ د آواز په شان، لکه د فوجيانو شور. او کله چې هغوئ ودرېدل نو وزرونه يې ښکته کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19376, 'Ezekiel 1:25', 'Ezekiel', 1, 25, '&nbsp;نو بيا د ګنبد دپاسه د هغوئ په سر يو آواز راغلو. کله چې هغوئ ودرېدل نو وزرونه يې ښکته کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19377, 'Ezekiel 1:26', 'Ezekiel', 1, 26, '&nbsp;د هغوئ د سرونو دپاسه په ګنبد باندې د نيلم کاڼى د تخت په شان يو څيز ښکارېدو، او د هغه تخت دپاسه د انسان په شان يو شکل او صورت ښکارېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19378, 'Ezekiel 1:27', 'Ezekiel', 1, 27, '&nbsp;دا کوم شکل چې ښکارېدو د ملا نه بره لکه ګرم شوې اوسپنې په شان چې د اور نه ډکه وى، او ملا نه لاندې لکه د اور په شان ښکارېدو، او ګېرچاپېره ترې صفا رڼا وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19379, 'Ezekiel 1:28', 'Ezekiel', 1, 28, '&nbsp;لکه څنګه چې په باران کښې د بوډۍ ټال په وريځ کښې په مختلفو رنګونو کښې وى دغه شان رڼاګانې د هغۀ نه هم راوچتېدلې. نو دا منظر د مالِک خُدائ د جلال په شان ښکاره کېدلو. کله چې ما دا هر څۀ وليدل، نو زۀ په زمکه پړمخې پرېوتلم او ما يو آواز واورېدو چې ما ته يې خبرې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19380, 'Ezekiel 2:1', 'Ezekiel', 2, 1, '&nbsp;هغۀ ما ته وفرمائيل چې، ”اے بنى آدمه پاڅه په خپلو پښو ودرېږه، زۀ تا سره خبرې کول غواړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19381, 'Ezekiel 2:2', 'Ezekiel', 2, 2, '&nbsp;کله چې هغۀ ما ته خبرې کولې، د خُدائ پاک روح په ما کښې راننوتو او زۀ يې په خپلو پښو ودرولم، نو ما د هغۀ خبرې واورېدلې چې ما ته يې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19382, 'Ezekiel 2:3', 'Ezekiel', 2, 3, '&nbsp;هغۀ ما ته وفرمائيل، ”اے بنى آدمه، زۀ تا بنى اِسرائيلو له لېږم، يو سرکشه قوم له چا چې زما خلاف سرکشى کړې ده. د اول نه تر نن ورځې پورې دوئ په خپله او د دوئ پلار نيکۀ زما نافرمانى کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19383, 'Ezekiel 2:4', 'Ezekiel', 2, 4, '&nbsp;کومو خلقو ته چې زۀ تا استوم هغوئ ضديان او سخت طبيعته دى. هغوئ ته ووايه چې مالِک قادر مطلق خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19384, 'Ezekiel 2:5', 'Ezekiel', 2, 5, '&nbsp;کۀ دا سرکشه قوم ستا خبرو ته غوږ نيسى او کۀ نۀ نيسى خو په دې به پوهه وى چې زمونږ په مينځ کښې يو پېغمبر موجود دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19385, 'Ezekiel 2:6', 'Ezekiel', 2, 6, '&nbsp;خو تۀ، اے بنى آدمه، د هغوئ نه او د هغوئ د خبرو نه مۀ يرېږه. کۀ د هغوئ دهمکى تا د ازغو او يا د لړمانو په شان راګېر هم کړى. مۀ د هغوئ خبرو نه يرېږه، مۀ د هغوئ د نېغو کتلو نه يرېږه، ځکه چې دا قوم سرکشه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19386, 'Ezekiel 2:7', 'Ezekiel', 2, 7, '&nbsp;تۀ زما کلام هغوئ ته ووايه، کۀ هغوئ ورته غوږ نيسى او کۀ نۀ نيسى، ځکه چې هغوئ بلکل سرکشه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19387, 'Ezekiel 2:8', 'Ezekiel', 2, 8, '&nbsp;خو تۀ، اے بنى آدمه، هغه څۀ ته غوږ ونيسه څۀ چې زۀ تا ته وايم. د دغه سرکشه قوم په شان مۀ جوړېږه، تۀ دې خپله خولۀ کولاو کړه او هر هغه څۀ وخوره څۀ چې زۀ درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19388, 'Ezekiel 2:9', 'Ezekiel', 2, 9, '&nbsp;نو ما بيا وليدل چې يو لاس زما طرف ته راغزېدلے دے او د هغۀ سره يو طومار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19389, 'Ezekiel 2:10', 'Ezekiel', 2, 10, '&nbsp;کوم طومار چې هغۀ زما په وړاندې کولاو کړو، د هغې په دواړو خواو کښې د ماتم، غم او افسوس خبرې ليکلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19390, 'Ezekiel 3:1', 'Ezekiel', 3, 1, '&nbsp;او هغۀ ما ته وفرمائيل، ”اے بنى آدمه، دا څۀ چې ستا په وړاندې دى دا وخوره، دا طومار وخوره، نو بيا لاړ شه او بنى اِسرائيلو ته يې بيان کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19391, 'Ezekiel 3:2', 'Ezekiel', 3, 2, '&nbsp;نو بيا ما خپله خولۀ کولاو کړه او هغۀ ما له هغه طومار راکړو چې وې خورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19392, 'Ezekiel 3:3', 'Ezekiel', 3, 3, '&nbsp;نو بيا هغۀ ما ته وفرمائيل چې، ”اے بنى آدمه، زۀ چې کوم طومار تا له درکوم دا وخوره او خپله خېټه پرې مړه کړه.“ نو بيا ما هغه وخوړو، او هغې زما په خولۀ کښې لکه د شاتو په شان خوږ خوند کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19393, 'Ezekiel 3:4', 'Ezekiel', 3, 4, '&nbsp;نو بيا هغۀ ما ته وفرمائيل، ”اے بنى آدمه، اوس بنى اِسرائيلو له ورشه او زما کلام هغوئ ته واوروه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19394, 'Ezekiel 3:5', 'Ezekiel', 3, 5, '&nbsp;زۀ تا داسې خلقو ته نۀ استوم چې د هغوئ ژبه ستا دپاره نا آشنا او سخته وى خو تا زۀ بنى اِسرائيلو ته استوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19395, 'Ezekiel 3:6', 'Ezekiel', 3, 6, '&nbsp;زۀ تا هغه ډېرو خلقو ته نۀ استوم چې د چا په ژبه به پوهېدل تا ته ګران وى او د هغې الفاظ به مختلف وى او تۀ به پرې نۀ پوهېږې. خو کۀ چرې تۀ ما هغوئ ته لېږلے وے، نو هغوئ به بيا تا ته غوږ نيولے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19396, 'Ezekiel 3:7', 'Ezekiel', 3, 7, '&nbsp;خو د بنى اِسرائيلو قوم نۀ غواړى چې تا ته غوږ ونيسى ځکه چې هغوئ نۀ غواړى چې ما ته غوږ ونيسى، ځکه د بنى اِسرائيلو ټول قوم ضدى او په زړۀ سخت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19397, 'Ezekiel 3:8', 'Ezekiel', 3, 8, '&nbsp;خو ګوره، زۀ به تا هم د هغوئ په شان ضدى او په زړۀ سخت کړم لکه څنګه چې هغوئ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19398, 'Ezekiel 3:9', 'Ezekiel', 3, 9, '&nbsp;او زۀ به ستا تندے لکه د سخت او کلک ګټ په شان کړم، او د هيرې نه به يې هم سخت کړم. تۀ د هغوئ نه مۀ يرېږه او مۀ ترې نه په دهشت کښې پرېوځه کۀ څۀ هم چې دا قوم سرکشه دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19399, 'Ezekiel 3:10', 'Ezekiel', 3, 10, '&nbsp;او هغۀ راته وفرمائيل چې، ”اے بنى آدمه، ما ته غوږ ونيسه ټول کلام چې زۀ درته وايم هغه په غور سره واوره او په خپل زړۀ کښې يې واچوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19400, 'Ezekiel 3:11', 'Ezekiel', 3, 11, '&nbsp;نو اوس د خپل قوم خلقو له ورشه څوک چې جلاوطن شوى دى او هغوئ سره خبرې وکړه. هغوئ ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى، دا چې هغوئ ستا خبرو ته غوږ نيسى او کۀ نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');